const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Córdoba airport coordinates (approx. -31.3169, -64.2192)
  const airport = ee.Geometry.Point([-64.2192, -31.3169]);
  const date = ee.Date('2023-04-26');
  const nextDay = date.advance(1, 'day');

  // 2. Data Acquisition
  const collection = ee.ImageCollection('MODIS/061/MOD11A1')
    .filterDate(date, nextDay)
    .filterBounds(airport);

  // Check if collection is empty
  const collectionSize = await collection.size().getInfo();
  if (collectionSize === 0) {
    console.log("No MODIS MOD11A1 images found for April 26, 2023 at Córdoba airport.");
    console.log("C1");
    return;
  }

  // Get the single image for the day
  const image = collection.first();

  // 3. Processing - Quality Masking and LST Conversion
  // MODIS LST values are scaled by 0.02 and are in Kelvin.
  // Convert to Celsius: (LST * 0.02) - 273.15
  // QC_Day band explanation (from MOD11A1 product page):
  // Bit 0-1: LST quality (00 = good quality)
  // Bit 2-3: Day clear sky coverage (00 = pixel produced, not cloudy)
  // Mask out pixels where LST quality is not good or not clear sky.
  const lstDay = image.select('LST_Day_1km');
  const qcDay = image.select('QC_Day');

  // Select good quality LST and clear sky (bits 0-3 are 0000)
  const goodQualityAndClear = qcDay.bitwiseAnd(ee.Image(15)).eq(0); // 15 = 0b1111

  // Mask the LST band with the quality mask
  const maskedLST = lstDay.updateMask(goodQualityAndClear);

  // Convert LST from Kelvin*0.02 to Celsius
  const lstCelsius = maskedLST.multiply(0.02).subtract(273.15);

  // 4. Calculation - Extract temperature at airport
  // Use a scale of 1000m as MOD11A1 resolution is 1km
  const temperatureResult = await lstCelsius.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: airport,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km').getInfo();

  // Check for C2/C3
  if (temperatureResult === null || isNaN(temperatureResult)) {
    // Check if there were any valid pixels before the calculation
    const validPixelCount = await lstCelsius.reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: airport,
      scale: 1000,
      maxPixels: 1e9
    }).get('LST_Day_1km').getInfo();

    if (validPixelCount === 0) {
      console.log("No valid pixels at Córdoba airport after quality masking (likely due to clouds).");
      console.log("C2");
    } else {
      console.log("Calculation failure: Temperature result is null or NaN.");
      console.log("C3");
    }
    return;
  }

  const tempC = temperatureResult;
  console.log(`Temperature at Córdoba airport on 2023-04-26: ${tempC.toFixed(2)} °C`);

  // 5. Validation & Final Answer
  const threshold = 40;
  if (tempC > threshold) {
    console.log("A"); // Yes
  } else {
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
